/**
 * stealth.min.js —— 自写精简版反自动化检测脚本（非 requireCool 原版）
 *
 * 为什么不用原版：原版托管在 GitHub raw，国内拉取不稳定，且本项目只需要覆盖
 * 小红书风控实际检查的那几项。这里保留的检测点都是「不修就会被判定为机器人」的：
 *   1. navigator.webdriver          —— Playwright 默认 true，最致命的一项
 *   2. navigator.plugins/mimeTypes  —— headless 下为空数组，一眼假
 *   3. window.chrome.runtime        —— 真 Chrome 必有，CDP 环境缺失
 *   4. iframe 内的 webdriver        —— 只在主 frame 打补丁会被 iframe 检测绕过
 *   5. permissions.query            —— 通知权限查询结果异常
 *   6. WebGL vendor/renderer        —— headless 暴露 "Google SwiftShader"
 *
 * 注：小红书的 x-s 签名风控另有一层（设备指纹 + 行为），本脚本只解决
 * 「一眼假」的静态特征，行为侧由 ratelimit 配置负责。
 */
(() => {
  'use strict';

  const patch = (win) => {
    const desc = (obj, prop, value) => {
      try {
        Object.defineProperty(obj, prop, { get: () => value, configurable: true });
      } catch (e) {}
    };

    // 1. webdriver
    try {
      Object.defineProperty(win.navigator, 'webdriver', { get: () => undefined, configurable: true });
      delete win.navigator.webdriver;
    } catch (e) {}
    desc(win.navigator, 'webdriver', undefined);

    // 2. plugins / mimeTypes（真 Chrome 有 5 个内置插件）
    const makePlugin = (name, filename, desc_) => {
      const p = Object.create(Plugin.prototype);
      desc(p, 'name', name);
      desc(p, 'filename', filename);
      desc(p, 'description', desc_);
      desc(p, 'length', 1);
      return p;
    };
    const plugins = [
      makePlugin('PDF Viewer', 'internal-pdf-viewer', 'Portable Document Format'),
      makePlugin('Chrome PDF Viewer', 'internal-pdf-viewer', 'Portable Document Format'),
      makePlugin('Chromium PDF Viewer', 'internal-pdf-viewer', 'Portable Document Format'),
      makePlugin('Microsoft Edge PDF Viewer', 'internal-pdf-viewer', 'Portable Document Format'),
      makePlugin('WebKit built-in PDF', 'internal-pdf-viewer', 'Portable Document Format'),
    ];
    const pluginArray = Object.create(PluginArray.prototype);
    plugins.forEach((p, i) => { pluginArray[i] = p; });
    desc(pluginArray, 'length', plugins.length);
    desc(win.navigator, 'plugins', pluginArray);

    const mimeTypes = Object.create(MimeTypeArray.prototype);
    desc(mimeTypes, 'length', 2);
    desc(win.navigator, 'mimeTypes', mimeTypes);

    // 3. window.chrome
    if (!win.chrome) {
      const chrome = {};
      desc(chrome, 'runtime', {
        id: undefined,
        connect: () => {},
        sendMessage: () => {},
        onMessage: { addListener: () => {}, removeListener: () => {} },
      });
      desc(chrome, 'app', { isInstalled: false, InstallState: {}, RunningState: {} });
      desc(chrome, 'csi', () => {});
      desc(chrome, 'loadTimes', () => {});
      desc(win, 'chrome', chrome);
    }

    // 4. languages
    desc(win.navigator, 'languages', ['zh-CN', 'zh', 'en-US', 'en']);
    desc(win.navigator, 'hardwareConcurrency', 8);
    desc(win.navigator, 'deviceMemory', 8);
    desc(win.navigator, 'maxTouchPoints', 0);

    // 5. permissions.query —— notifications 在自动化环境下返回 prompt 而非 denied
    if (win.navigator.permissions && win.navigator.permissions.query) {
      const origQuery = win.navigator.permissions.query.bind(win.navigator.permissions);
      win.navigator.permissions.query = (params) =>
        params && params.name === 'notifications'
          ? Promise.resolve({ state: Notification.permission, onchange: null })
          : origQuery(params);
    }

    // 6. WebGL —— headless 的 SwiftShader 是最容易被识别的特征
    //    ★ 关键：检测脚本优先读 WEBGL_debug_renderer_info 的 UNMASKED_* (0x9245/0x9246)，
    //      只覆盖标准的 VENDOR/RENDERER (0x1f00/0x1f01) 会被直接绕过。两组都要改。
    const overrideWebGL = (proto) => {
      if (!proto) return;
      const orig = proto.getParameter;
      proto.getParameter = function (p) {
        if (p === 0x1f00 || p === 0x9245) return 'Google Inc. (Intel)';   // VENDOR / UNMASKED_VENDOR
        if (p === 0x1f01 || p === 0x9246) return 'ANGLE (Intel, Intel(R) HD Graphics 5500 Direct3D11 vs_5_0 ps_5_0, D3D11)'; // RENDERER / UNMASKED_RENDERER
        if (p === 0x8b8c) return 'WebGL 1.0 (OpenGL ES 2.0 Chromium)';    // SHADING_LANGUAGE_VERSION
        return orig.apply(this, arguments);
      };
    };
    overrideWebGL(win.WebGLRenderingContext && win.WebGLRenderingContext.prototype);
    overrideWebGL(win.WebGL2RenderingContext && win.WebGL2RenderingContext.prototype);

    // 7. 抹掉 CDP 注入痕迹：Runtime.enable 会把 console 对象挂上调试引用
    try {
      const origToString = Function.prototype.toString;
      const nativeNames = new Set([
        'connect', 'sendMessage', 'query', 'getParameter', 'toString',
      ]);
      Function.prototype.toString = function () {
        if (nativeNames.has(this.name)) return `function ${this.name}() { [native code] }`;
        return origToString.call(this);
      };
    } catch (e) {}
  };

  // 主 frame
  patch(window);

  // iframe：只在主 frame 打补丁，检测脚本从 iframe 里读 navigator 就露馅了
  const origAttach = HTMLIFrameElement.prototype.__lookupGetter__('contentWindow');
  try {
    Object.defineProperty(HTMLIFrameElement.prototype, 'contentWindow', {
      get: function () {
        const win = origAttach.call(this);
        if (win) { try { patch(win); } catch (e) {} }
        return win;
      },
      configurable: true,
    });
  } catch (e) {}

  // 动态创建的 iframe（createElement 路径不走上面的 getter）
  const origAppend = Element.prototype.appendChild;
  Element.prototype.appendChild = function (node) {
    const ret = origAppend.apply(this, arguments);
    if (node && node.tagName === 'IFRAME') {
      try { patch(node.contentWindow); } catch (e) {}
    }
    return ret;
  };
})();
